// And groups predicates with the AND operator between them.
func And(predicates ...predicate.WorkBlocker) predicate.WorkBlocker {
	return predicate.WorkBlocker(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.WorkBlocker) predicate.WorkBlocker {
	return predicate.WorkBlocker(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.WorkBlocker) predicate.WorkBlocker {
	return predicate.WorkBlocker(sql.NotPredicates(p))
}
